"""Passive final-evaluation tracing plus fail-closed authorized effect ceilings.

Does not import/call any Bridge delivery, renderer or SMTP entry point.
Never records configuration dictionaries, environments or SMTP login arguments.
"""
import dataclasses
import json
import os
from pathlib import Path
import sys
import time

ROOT = Path('/tmp/bridge-final-replacement-9ggq9knx')
TRACE = ROOT / 'trace'
TRACE.mkdir(exist_ok=True)
SEQ = 0


def audit_json_default(value):
    if isinstance(value, os.PathLike):
        return os.fspath(value)
    raise TypeError('Unsupported observer value: ' + type(value).__name__)


def record(kind, data):
    global SEQ
    SEQ += 1
    payload = dict(kind=kind, pid=os.getpid(), ppid=os.getppid(),
                   wall_time=time.time(), monotonic=time.monotonic(), data=data)
    path = TRACE / ('%s-%s-%s.json' % (os.getpid(), SEQ, kind))
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2, default=audit_json_default) + '\n', encoding='utf-8')


def reserve(kind):
    for index in range(2):
        path = TRACE / ('budget-%s-%s.json' % (kind, index))
        try:
            descriptor = os.open(str(path), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        except FileExistsError:
            continue
        with os.fdopen(descriptor, 'w') as stream:
            json.dump(dict(pid=os.getpid(), ppid=os.getppid(), time=time.time()), stream)
        return
    record('BUDGET_EXCEEDED', dict(effect=kind))
    raise RuntimeError('FINAL_EVALUATION_EFFECT_BUDGET_EXCEEDED:' + kind)


def audit(event, args):
    if event == 'subprocess.Popen':
        argv = args[1]
        if isinstance(argv, (tuple, list)):
            argv = [str(x) for x in argv]
            if len(argv) > 1 and Path(argv[0]).name == 'codex' and argv[1] == 'exec':
                if argv != ['/users/a/e/aereinh/bin/codex', 'exec', '--ephemeral', '--json',
                            '--sandbox', 'read-only', '--skip-git-repo-check', '-C',
                            '/users/a/e/aereinh/.ai-bridge/clear-writing', '-']:
                    raise RuntimeError('UNAPPROVED_MODEL_ARGV')
                reserve('model')
                record('model_spawn', dict(argv=argv, cwd=str(args[2]) if args[2] is not None else None))
            elif '_supervise' in argv or '_deliver-helper' in argv or 'child.py' in argv:
                record('process_spawn', dict(argv=argv, cwd=str(args[2]) if args[2] is not None else None))
    elif event == 'smtplib.connect':
        host, port = args[1], args[2]
        if host != 'smtp.gmail.com' or port != 587:
            raise RuntimeError('UNAPPROVED_SMTP_DESTINATION')
        reserve('smtp')
        record('smtp_connect', dict(host=host, port=port))


def result_data(value):
    return dataclasses.asdict(value) if dataclasses.is_dataclass(value) else value


def profile(frame, event, value):
    if event not in ('call', 'return'):
        return
    module = frame.f_globals.get('__name__', '')
    name = frame.f_code.co_name
    local = frame.f_locals
    notifier = frame.f_code.co_filename.endswith('/ai_bridge_kit/notifier.py')
    if module in ('ai_bridge_kit.persistent_run', '__main__') and name == '_persistent_notification':
        binding = local['binding']
        if event == 'call':
            if local['fact_class'] not in ('runtime_start', 'runtime_terminal'):
                raise RuntimeError('UNAPPROVED_THIRD_LOGICAL_EVENT')
            if binding['repo_realpath'] != str(ROOT / 'public-canary'):
                raise RuntimeError('UNAPPROVED_CANARY_REPO')
            record('supervisor_notification_call', dict(fact_class=local['fact_class'],
                   child_pid=binding.get('child_pid'), launch_id=binding['launch_id'],
                   run_key=binding['run_key'], status=local['status']))
        else:
            record('supervisor_notification_return', dict(fact_class=local['fact_class'],
                   request=local.get('request'), delivery=result_data(local.get('delivery')),
                   last_notification=binding.get('last_notification')))
    elif notifier and name == 'deliver_notification':
        if event == 'call':
            record('delivery_call', dict(request=local['request'], caller=frame.f_back.f_code.co_name,
                   caller_module=frame.f_back.f_globals.get('__name__')))
        else:
            record('delivery_return', result_data(value))
    elif notifier and name == 'deliver_event_inline' and event == 'return':
        record('helper_return', dict(request=local.get('request'), rendered=local.get('rendered'),
               attempt=local.get('attempt'), result=result_data(value), directory=str(local['directory'])))
    elif module == 'ai_bridge_kit.clear_writing' and name == 'render_once' and event == 'return':
        record('render_return', dict(brief=local['brief'], result=value))
    elif module == 'ai_bridge_kit.clear_writing' and name == '_prompt' and event == 'return':
        record('prompt', dict(text=value))
    elif module == 'subprocess' and name == 'run':
        popenargs = local.get('popenargs', ())
        argv = popenargs[0] if popenargs else []
        if isinstance(argv, (list, tuple)) and len(argv) > 1 and Path(str(argv[0])).name == 'codex' and argv[1] == 'exec':
            if event == 'call':
                record('model_run_call', dict(argv=argv, prompt=local.get('kwargs', {}).get('input')))
            elif value is not None:
                record('model_run_return', dict(argv=argv, returncode=value.returncode,
                       stdout=value.stdout, stderr=value.stderr))
    elif notifier and name == 'build_auto_email' and event == 'return' and value is not None:
        record('email_built', dict(mime=value.as_string(), body=value.get_body(preferencelist=('plain',)).get_content(),
               subject=str(value['Subject']), sender=str(value['From']), recipient=str(value['To'])))
    elif module == 'smtplib' and name == 'send_message':
        if event == 'call':
            record('smtp_send_message_call', dict(subject=str(local['msg']['Subject'])))
        else:
            record('smtp_send_message_return', dict(result=value))


record('python_start', dict(argv=sys.argv, executable=sys.executable))
sys.addaudithook(audit)
sys.setprofile(profile)
